// Simple pptxgenjs script to create a presentation
const PptxGenJS = require('pptxgenjs');
let pres = new PptxGenJS();

// Set layout to 16x9 (default)
pres.layout = 'LAYOUT_16x9';

// Title slide
let slide = pres.addSlide();
slide.addText('Sample Presentation', { x: 0.5, y: 0.5, fontSize: 32, color: '366092' });
slide.addText('Created with pptxgenjs', { x: 0.5, y: 1.5, fontSize: 20, color: '666666' });

// Bullet slide
slide = pres.addSlide();
slide.addText('Agenda', { x: 0.5, y: 0.5, fontSize: 24, color: '366092' });
slide.addText([
  'Introduction',
  'Main Topics',
  'Conclusion',
  'Q&A'
], { x: 0.5, y: 1.5, fontSize: 18, color: '000000', bullet: true, breakLine: true });

// Save the presentation
pres.writeFile({ fileName: 'Desktop/presentation.pptx' });

